package com.library.ui; import com.library.model.*; import com.library.service.*; import com.library.session.SessionManager; import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*; import java.math.BigDecimal; import java.util.*;
public class MemberDashboard extends JFrame { private final Member member;private final LibraryService library=new LibraryService();public MemberDashboard(Member member){super("Smart Library System - Student");this.member=member;setSize(1000,600);setMinimumSize(new Dimension(760,500));setLocationRelativeTo(null);setDefaultCloseOperation(EXIT_ON_CLOSE);JPanel root=new JPanel(new BorderLayout());JPanel h=new JPanel(new BorderLayout());h.setBackground(UI.NAVY);JLabel welcome=new JLabel("  Welcome, "+member.getName());welcome.setForeground(Color.WHITE);welcome.setFont(welcome.getFont().deriveFont(Font.BOLD,18f));h.add(welcome,BorderLayout.WEST);JButton logout=new JButton("Logout");logout.addActionListener(e->{SessionManager.logout();dispose();new RoleSelectionFrame().setVisible(true);});h.add(logout,BorderLayout.EAST);root.add(h,BorderLayout.NORTH);root.add(content());add(root);} private JComponent content(){try{java.util.List<Transaction> tx=library.myTransactions(member.getMemberId());long issued=tx.stream().filter(t->t.getReturnDate()==null).count(), overdue=tx.stream().filter(t->t.getReturnDate()==null&&t.getDueDate().isBefore(java.time.LocalDate.now())).count(), due=tx.stream().filter(t->t.getReturnDate()==null&&!t.getDueDate().isBefore(java.time.LocalDate.now())&&t.getDueDate().isBefore(java.time.LocalDate.now().plusDays(4))).count();BigDecimal fine=tx.stream().map(Transaction::getFine).reduce(BigDecimal.ZERO,BigDecimal::add);JPanel p=new JPanel(new BorderLayout(12,12));p.setBorder(BorderFactory.createEmptyBorder(18,18,18,18));JPanel cards=new JPanel(new GridLayout(1,4,12,12));cards.add(UI.card("Currently Issued",String.valueOf(issued)));cards.add(UI.card("Due Soon",String.valueOf(due)));cards.add(UI.card("Overdue",String.valueOf(overdue)));cards.add(UI.card("My Fine",UI.rupee(fine)));p.add(new JScrollPane(cards),BorderLayout.NORTH);DefaultTableModel m=new DefaultTableModel(new String[]{"Book","Issue Date","Due Date","Return Date","Fine","Status"},0);for(Transaction t:tx)m.addRow(new Object[]{t.getBookName(),t.getIssueDate(),t.getDueDate(),t.getReturnDate(),UI.rupee(t.getFine()),t.getStatus()});JTabbedPane tabs=new JTabbedPane();tabs.add("My Borrowing History",new JScrollPane(new JTable(m)));tabs.add("My Profile",profile());p.add(tabs,BorderLayout.CENTER);return p;}catch(Exception e){JPanel p=new JPanel();p.add(new JLabel(e.getMessage()));return p;}} private JComponent profile(){JPanel p=new JPanel(new GridLayout(0,2,10,10));p.setBorder(BorderFactory.createEmptyBorder(25,25,25,25));String[][] x={{"Enrollment Number",String.valueOf(member.getMemberId())},{"Name",member.getName()},{"Email",member.getEmail()},{"Phone",member.getPhone()},{"Course",member.getCourse()},{"Department",member.getDepartment()},{"Semester",String.valueOf(member.getSemester())}};for(String[] a:x){p.add(new JLabel(a[0]+":"));p.add(new JLabel(a[1]));}return p;} }
